    <script>
        const scene = new THREE.Scene();
        const camera = new THREE.PerspectiveCamera(75, window.innerWidth / window.innerHeight, 0.1, 1000);
        const renderer = new THREE.WebGLRenderer({ alpha: true });
        renderer.setSize(window.innerWidth, window.innerHeight);
        document.getElementById("waveform3d").appendChild(renderer.domElement);

        const points = [];
        for (let i = 0; i < 200; i++) {
            points.push(new THREE.Vector3(i / 10, Math.sin(i / 10) * 0.5, 0));
        }
        const geometry = new THREE.BufferGeometry().setFromPoints(points);
        const material = new THREE.LineBasicMaterial({ color: 0x8B5CF6 });
        const waveform = new THREE.Line(geometry, material);
        scene.add(waveform);

        camera.position.z = 5;

        function animate() {
            requestAnimationFrame(animate);
            waveform.rotation.y += 0.002;
            waveform.rotation.x += 0.001;
            renderer.render(scene, camera);
        }
        animate();
    </script>

    <!-- 3D Beat Grid -->
    <script>
        const gridScene = new THREE.Scene();
        const gridCamera = new THREE.PerspectiveCamera(60, window.innerWidth / 300, 0.1, 1000);
        const gridRenderer = new THREE.WebGLRenderer({ alpha: true });
        gridRenderer.setSize(window.innerWidth, 350);
        document.getElementById("beatGrid3d").appendChild(gridRenderer.domElement);

        const gridGeometry = new THREE.PlaneGeometry(20, 20, 20, 20);
        const gridMaterial = new THREE.MeshBasicMaterial({
            color: 0x3B82F6,
            wireframe: true
        });
        const grid = new THREE.Mesh(gridGeometry, gridMaterial);
        grid.rotation.x = -Math.PI / 2.5;
        gridScene.add(grid);

        gridCamera.position.z = 10;

        function animateGrid() {
            requestAnimationFrame(animateGrid);
            grid.rotation.z += 0.002;
            gridRenderer.render(gridScene, gridCamera);
        }
        animateGrid();
