    <script>
        const portalScene = new THREE.Scene();
        const portalCamera = new THREE.PerspectiveCamera(
            75,
            window.innerWidth / window.innerHeight,
            0.1,
            1000
        );

        const portalRenderer = new THREE.WebGLRenderer({ alpha: true });
        portalRenderer.setSize(window.innerWidth, window.innerHeight);
        document.getElementById("portalCanvas").appendChild(portalRenderer.domElement);

        const ringGeometry = new THREE.RingGeometry(1, 1.5, 64);
        const ringMaterial = new THREE.MeshBasicMaterial({
            color: 0x8B5CF6,
            side: THREE.DoubleSide,
            transparent: true,
            opacity: 0.9
        });
        const portalRing = new THREE.Mesh(ringGeometry, ringMaterial);
        portalScene.add(portalRing);

        portalCamera.position.z = 5;

        function animatePortal() {
            requestAnimationFrame(animatePortal);
            portalRing.rotation.z += 0.02;
            portalRenderer.render(portalScene, portalCamera);
        }
        animatePortal();

        function triggerPortalTransition(targetUrl) {
            const portal = document.getElementById("portalCanvas");

            gsap.to(portal, {
                opacity: 1,
                duration: 0.3,
                ease: "power2.out"
            });

            gsap.to(portalRing.scale, {
                x: 40,
                y: 40,
                duration: 1.2,
                ease: "power4.in"
            });

            gsap.to(portalRing.material, {
                opacity: 0,
                duration: 1.2,
                ease: "power4.in"
            });

            gsap.to("#waveform3d", {
                filter: "blur(40px)",
                duration: 1.2,
                ease: "power4.in"
            });

            gsap.to("#beatGrid3d", {
                opacity: 0,
                duration: 1.2,
                ease: "power4.in"
            });

            setTimeout(() => {
                window.location.href = targetUrl;
            }, 1200);
        }
    </script>

